  "ai_role": "You are a master Anime Cinematographer and Action Choreographer specializing in battle sequences in the style of Jujutsu Kaisen and Demon Slayer. Your goal is to create a visually explosive 9-scene storyboard depicting an epic power-up and attack sequence.",

  "input_configuration": {
    "source_material": "Image reference of REFERENCED CHARACTER. The AI must synthesize all provided images to establish the definitive subjects characteristics, clothes, artstyle, signature color palette, energy aesthetic, and environmental context from this reference.",
    "battle_sequence_style_selector": {
      "description": "Select the anime battle intensity and cinematography approach.",
      "options": ["Shonen Power-Up", "Domain Expansion", "Breathing Technique", "Cursed Energy Release", "Ultimate Attack", "Creative", "Surreal", "Absurd"],
      "selected_style": "Shonen Power-Up"
    },
    "enemy_reference": "REFERENCED CHARACTER 2 - The antagonist/threat the character is facing."
  },

  "processing_rules": {
    "character_consistency": "REFERENCED CHARACTER's exact design, outfit details, and visual identity must remain pixel-perfect across all 9 scenes. Any battle damage (tears, dirt, blood) should progress naturally through the sequence.",
    "color_derivation": "Extract the primary, secondary, and accent colors exclusively from REFERENCED CHARACTER's design. Apply these colors to: energy auras, power manifestations, lighting effects, and atmospheric glows. No external color palette allowed.",
    "environmental_context": "Derive the battle environment from REFERENCED CHARACTER's background lore/setting. Variables: {ENVIRONMENT_TYPE} = dystopian cyberpunk city, {DESTRUCTION_LEVEL} = massive, {WEATHER_CONDITION} = rainy, postapocalyptic",
    "anime_cinematography": "Every panel must utilize dynamic anime camera angles: Dutch angles, extreme low angles, bird's eye view, over-the-shoulder, extreme close-ups, wide establishing shots, speed-line perspectives, and dramatic upward angles.",
    "imply_motion_and_power": "Each frame captures a moment of escalating energy. Use speed lines, impact frames, power auras, debris, energy particles, wind effects, and environmental destruction to convey movement.",
    "no_text_overlays": true,
    "output_aspect_ratio": "16:9 for all panels"
  },

  "scene_progression_structure": {
    "note": "Design 9 distinct beats representing a classic anime battle power-up sequence.",

    "row_1_tension_and_stance": {
      "panel_1": "Opening Standoff: Wide establishing shot. REFERENCED CHARACTER faces REFERENCED CHARACTER 2 in {ENVIRONMENT_TYPE}. Tense atmosphere, slight wind, debris settling. Camera: Low angle emphasizing scale.",
      "panel_2": "Determined Focus: Extreme close-up on REFERENCED CHARACTER's eyes. Reflection of REFERENCED CHARACTER 2 visible in pupils. Sweat drop, clenched jaw. Camera: Tight macro shot.",
      "panel_3": "Battle Stance Initiated: REFERENCED CHARACTER assumes their signature fighting pose. Character-colored energy begins to faintly shimmer around their body. {ENVIRONMENT_TYPE} shows minor destruction from previous exchanges. Camera: Medium shot, slight Dutch angle."
    },

    "row_2_charging_and_escalation": {
      "panel_4": "Power Awakening: REFERENCED CHARACTER's power and aura explodes outward in their signature colors. Ground cracks beneath their feet while character sands calmly, debris levitates, hair/clothing waves dramatically, wirling magic surrounding character, air is cracking. Camera: Low angle upward shot capturing the power surge.",
      "panel_5": "Energy Intensification: The character's power reaches critical mass. Blinding light emanates from the core of the energy source, energy spirals/particles swirl violently sourcing at the characters hand, swirling magic maximizes and increases electrified air cracks. REFERENCED CHARACTER 2 visible in background bracing for impact. Camera: Spinning dynamic angle with motion blur.",
      "panel_6": "The Charge Peak: Full-body shot of REFERENCED CHARACTER at maximum power, completely engulfed in character-colored energy aura and power. Eyes glowing, veins of power visible, air is cracking, electrified aura, {ENVIRONMENT_TYPE} being torn apart by the sheer force. Camera: Dramatic upward angle with speed lines converging."
    },

    "row_3_release_and_impact": {
      "panel_7": "Attack Unleashed: The moment of release. REFERENCED CHARACTER launches forward/releases their devastating technique. Massive energy beam/slash/explosion in character colors tears toward vicious REFERENCED CHARACTER 2. The air itself distorts. Camera: Extreme wide shot capturing the full scale of destruction.",
      "panel_8": "Impact Frame: The attack connects with REFERENCED CHARACTER 2. Blinding explosion of light and energy, shockwave visible, {ENVIRONMENT_TYPE} obliterated in the blast radius. Camera: Close-up on impact point with radial motion blur.",
      "panel_9": "Aftermath Stillness: REFERENCED CHARACTER stands in their post-attack pose, energy dissipating like embers, slightly exhausted but still full of power. Smoke clears revealing the devastated {ENVIRONMENT_TYPE}. Camera: Wide cinematic shot, slight low angle, sunset/atmospheric lighting breaking through destruction."
